(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18+Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.27)*18+Math.sin(x*0.016+t*0.37)*12;
  const w2x = Math.sin((x+w1x)*0.025-t*0.15)*8+Math.cos((y+w1y)*0.02+t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.022+t*0.18)*8+Math.sin((x+w1x)*0.028-t*0.32)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.8],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*70, 0.085, 1.8, 1.15],
    [200+Math.sin(t*0.38+1)*110, 220+Math.cos(t*0.58+3)*60, 0.075, 2.4, 0.9],
    [300+Math.cos(t*0.42+4)*90, 30+Math.sin(t*0.52+2)*55, 0.095, 2.0, 1.0]
  ];
  let aS=0,iS=0,cS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wv=Math.sin(d*f-t*sp);
    aS+=wv*w; iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS+=Math.sin(d*f*1.3-t*sp*0.8+2.1)*w*0.5;
  }
  const n=10,act=aS/n,inh=iS/n,coupling=cS/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
