  const micro=Math.sin(sx*0.3+t*1.5)*Math.sin(sy*0.3-t*1.2)*Math.sin((sx+sy)*0.2+t*0.8)*0.15;
  const reaction=Math.tanh((act-inh*0.65+bg*0.25+spiral+coupling*0.4+micro)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.25;
  const pulse=0.95+Math.sin(t*0.8)*0.05+Math.sin(t*1.3+1)*0.03;
  const blend=(reaction*0.7+cell*0.2+coupling*0.1)*pulse;
  const v=blend*0.5+0.5;
  const edge=Math.abs(reaction);
  const glow=Math.exp(-edge*3)*0.4;
  const pal=[[5,12,52],[10,35,85],[12,65,105],[18,105,115],[40,145,130],[120,175,115],[195,185,80],[210,155,75],[195,110,75],[160,65,75],[100,35,70],[50,18,55],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+glow;
  const eBoost=edge>0.75?1.12+glow*0.5:1.0;
  const totalLum=lum*eBoost;
  return[Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f+glow*30)*totalLum)|0,Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f+glow*40)*totalLum)|0,Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f+glow*50)*totalLum)|0];
}
